insert into app.profiles (id, handle, name, badge, badge_color, tagline, bio, home_city, seeded, onboarded, sharing) values
  ('maren', 'marenonthe501', 'Maren Kowalczyk', 'MK', '#F7A6BF', 'the 501 streetcar is my listening room', 'Bookseller, Queen West. I will lend you a record and then think about it every day until you give it back.', 'Toronto', true, true, true),
  ('dev', 'dev.at.night', 'Devanshi Rao', 'DR', '#FFD23F', 'audio engineer. yes i can hear that. no i can’t fix it', 'Audio engineer by day. At night, also an audio engineer, but sad about it. Scarborough born, Dufferin bus raised.', 'Toronto', true, true, true),
  ('tobi', 'tobi.lifts.to.fela', 'Tobi Adeyemi', 'TA', '#7FCFA9', 'plays 12-minute songs at the gym. will not be taking questions', 'Mississauga. Afrobeat, highlife, and whatever my dad had on in the Camry.', 'Mississauga', true, true, true),
  ('priya', 'priyafrombrampton', 'Priya Gill', 'PG', '#F6B26B', 'brampton to the world. the aux is not a democracy', 'Punjabi rap, old Bollywood, and a deep bench of wedding bangers. Ask me about the 2021 AP Dhillon summer.', 'Brampton', true, true, true),
  ('callum', 'callum_in_the_pit', 'Callum Reid', 'CR', '#F0502F', 'seen PUP eleven times, twelve if you count the parking lot', 'East end. Line cook. If it has gang vocals I already love it and you can stop pitching.', 'Toronto', true, true, true),
  ('hana', 'hana.cant.hear.you', 'Hana Mori', 'HM', '#B9A7E8', 'shoegaze. sorry, what? no, i can’t hear you', 'North York. Pedal collector, reluctant guitarist. Believes reverb is a personality and is correct.', 'Toronto', true, true, true),
  ('sol', 'sol.leaves.at.one', 'Sol Benítez', 'SB', '#8FD3E8', 'club music for people who are home by 1', 'Vaughan. I love dancing and I love my bed and I refuse to choose.', 'Vaughan', true, true, true),
  ('wren', 'wren.plays.badly', 'Wren Abbott', 'WA', '#E7D36A', 'jazz piano and exactly one Nickelback song', 'Piano teacher in the Junction. I contain multitudes and one of them is from Alberta.', 'Toronto', true, true, true),
  ('amara', 'amara.after.hours', 'Amara Nwosu', 'AN', '#B9A7E8', 'r&b that sounds like 2 a.m., even at lunch', 'Scarborough. Nurse, night shifts. My commute playlist is the only thing keeping the 401 safe.', 'Toronto', true, true, true),
  ('jonah', 'jonah.has.notes', 'Jonah Feldman', 'JF', '#E7D36A', 'will explain Steely Dan to you. you will not be asked', 'Thornhill. Accountant with a hi-fi he can’t justify and a wife who has stopped asking.', 'Vaughan', true, true, true),
  ('kiran', 'kiran.on.the.go', 'Kiran Sandhu', 'KS', '#F6B26B', 'GO train DJ. audience of one. sold out nightly', 'Brampton to Union and back, five days a week. That’s ten hours of listening and I use all of it.', 'Brampton', true, true, true),
  ('bea', 'bea.on.dundas', 'Bea Carvalho', 'BC', '#FF9E80', 'has cried to Feist in the produce aisle. twice', 'Little Portugal. Florist. Everything I love was recorded in a church or sounds like it was.', 'Toronto', true, true, true),
  ('malik', 'malik.crates', 'Malik Thompson', 'MT', '#7FCFA9', 'my dad’s records. my problem now', 'Eglinton West. Inherited four hundred LPs and a strong opinion about each one.', 'Toronto', true, true, true),
  ('yuki', 'yuki.loops', 'Yuki Tanaka', 'YT', '#F7A6BF', 'one song. forty times. no notes', 'Markham. Animator. If I’m quiet it’s because the bridge is coming.', 'Markham', true, true, true),
  ('sofia', 'sofia.in.woodbridge', 'Sofia Marchetti', 'SM', '#FFD23F', 'nonna says it’s all noise. nonna is sometimes right', 'Woodbridge. Hairdresser. The salon speaker is mine and everybody knows it.', 'Vaughan', true, true, true),
  ('dez', 'dez.plays.bass', 'Dez Clarke', 'DC', '#8FD3E8', 'bass player. i know. i’m sorry', 'Wedding band on weekends, jazz trio on Tuesdays to feel something.', 'Toronto', true, true, true),
  ('ingrid', 'ingrid.by.the.lake', 'Ingrid Solberg', 'IS', '#5CC2B0', 'very quiet music. very loud opinions', 'The Beaches. I walk the boardwalk with one album a day and I do not take requests.', 'Toronto', true, true, true),
  ('mateo', 'mateo.sube.el.volumen', 'Mateo Rojas', 'MR', '#F0502F', 'perreo scholar. salsa by inheritance', 'St. Clair West. Barber. The chair spins and so does the playlist.', 'Toronto', true, true, true),
  ('farah', 'farah.skips.intros', 'Farah Haddad', 'FH', '#C6E377', 'skips the intro, then complains she missed it', 'Mississauga. Law student. I listen to sad songs efficiently.', 'Mississauga', true, true, true),
  ('owen', 'owen.cottage.country', 'Owen MacLeod', 'OM', '#E7D36A', 'the Hip are not up for debate', 'The Danforth. High school history teacher. Yes, I play it for the kids. No, they don’t get it yet.', 'Toronto', true, true, true),
  ('zainab', 'zainab.nightbus', 'Zainab Hussain', 'ZH', '#B9A7E8', 'the 320 night bus has the best acoustics in the city', 'Scarborough. Bartender. I hear everyone’s music all night, so the ride home is mine.', 'Toronto', true, true, true),
  ('theo', 'theo.eats.late', 'Theo Papadakis', 'TP', '#FF9E80', 'emo night survivor. two-time', 'Greektown. I work at my uncle’s restaurant and scream in the walk-in freezer as needed.', 'Toronto', true, true, true),
  ('grace', 'grace.practices', 'Grace Liu', 'GL', '#FFF6EC', 'conservatory kid, recovering', 'North York. Fourteen years of piano exams. I’m only now allowed to like things.', 'Toronto', true, true, true),
  ('rohan', 'rohan.at.square.one', 'Rohan Mehta', 'RM', '#8FD3E8', 'has a playlist for every mall he’s been dumped in', 'Mississauga. Software, unfortunately. Sad dad rock without being a dad.', 'Mississauga', true, true, true),
  ('niamh', 'niamh.in.parkdale', 'Niamh O’Connor', 'NO', '#7FCFA9', 'post-punk, pre-coffee', 'Parkdale via Cork. Came for a year in 2019. Still haven’t found a decent tea.', 'Toronto', true, true, true),
  ('jamal', 'jamal.aux.cord', 'Jamal Edwards', 'JE', '#FFD23F', 'banned from the aux at three separate barbecues', 'Brampton. I maintain that the transition was good and the crowd was wrong.', 'Brampton', true, true, true),
  ('clemence', 'clemence.en.ville', 'Clémence Bouchard', 'CB', '#F7A6BF', 'moved from Montréal. yes it was better. no i’m not leaving', 'Leslieville. Translator. I will defend this city in French so nobody here can hear me do it.', 'Toronto', true, true, true),
  ('arjun', 'arjun.left.the.band', 'Arjun Nair', 'AR', '#5CC2B0', 'left the band. the band is doing fine. it’s fine', 'Markham. Used to play guitar very loudly in a basement in Unionville. Now I do it in headphones like an adult.', 'Markham', true, true, true),
  ('lucia', 'lucia.from.maple', 'Lucia Ferrante', 'LF', '#F6B26B', 'drives in for the show, complains about parking through the encore', 'Maple. Dental hygienist. I’ve seen your favourite band and I had to leave early to beat traffic.', 'Vaughan', true, true, true),
  ('kwame', 'kwame.highlife', 'Kwame Mensah', 'KM', '#C6E377', 'highlife on sundays, whatever on the commute. range', 'Weston. Electrician. My van has better speakers than your apartment.', 'Toronto', true, true, true),
  ('hyejin', 'hyejin.bside', 'Hye-jin Park', 'HP', '#8FD3E8', 'b-sides only. i’m exhausting, i know', 'North York. Graphic designer. If it charted I’ll get to it in ten years and act like I found it.', 'Toronto', true, true, true),
  ('dmitri', 'dmitri.listens.loud', 'Dmitri Volkov', 'DV', '#F0502F', 'your neighbour. sorry about the subwoofer', 'Richmond Hill. I’ve had three noise complaints and one compliment, and I framed the compliment.', 'Richmond Hill', true, true, true),
  ('tessa', 'tessa.in.the.annex', 'Tessa Greenberg', 'TG', '#FFF6EC', 'grad student. this is my one personality', 'The Annex. Writing a thesis on something I can’t explain at parties. The music is easier to explain.', 'Toronto', true, true, true),
  ('andre', 'andre.selecta', 'Andre Baptiste', 'AB', '#7FCFA9', 'selector at family functions since age nine', 'Little Jamaica. I read a room faster than you read a menu.', 'Toronto', true, true, true),
  ('marisol', 'marisol.takes.the.mic', 'Marisol Vega', 'MV', '#F7A6BF', 'karaoke is a sport and i am nationally ranked', 'Port Credit. Thursdays at the pub by the lake. Do not sign up after me. It isn’t fair to you.', 'Mississauga', true, true, true),
  ('eli', 'eli.behind.the.counter', 'Eli Rosen', 'ER', '#E7D36A', 'will sell you a record, then judge you for it', 'Kensington Market. Record shop, weekends. The staff picks are all mine; the others have given up.', 'Toronto', true, true, true)
