insert into app.openers (user_id, track_id, note, after_accept) values
  ('priya', 'ap-dhillon-brown-munde', 'you had {artist} on near me and i respect it. your homework is this. report back.', 'ok you accepted. so did you actually listen or are you being polite'),
  ('callum', 'fucked-up-queen-of-hearts', '{title}? fine. good, even. now try something that yells at you.', 'there you are. be honest, how far in before you turned it down'),
  ('hana', 'cocteau-heaven-or-las-vegas', 'anyone playing {artist} in public deserves this. you can’t make out a single word and it doesn’t matter.', 'hi. sorry. i only really know how to talk about pedals. what did you think'),
  ('wren', 'nickelback-how-you-remind-me', 'i saw {title} and thought, this person has taste. so here is something to test it. sent with love.', 'you accepted the Nickelback. we can be friends. i have no follow-up, i didn’t think i’d get this far'),
  ('tobi', 'fela-water-no-get-enemy', '{artist} is a good start. this one is eleven minutes long and i need you to commit.', 'did you make it to the horns. be honest'),
  ('jonah', 'steely-dan-peg', 'noticed {title}. solid. have you considered that this has a better rhythm section? that was rhetorical.', 'thank you for accepting. i have four more recommendations and a short reading list'),
  ('bea', 'feist-mushaboom', 'you had {title} on and i thought, this person also cries in shops. this is for your walk home.', 'oh good, you said yes. i panicked right after sending it'),
  ('eli', 'pavement-gold-soundz', '{artist}. ok. i’ve seen worse come through the shop today. try this, it’s the staff pick.', 'so? that was a real question. i grade these'),
  ('marisol', 'shania-man-i-feel', '{title} is nice but can you SING it. this one you can sing. thursdays, i’ll save you a slot.', 'you accepted!! what’s your karaoke song. it’s the only question that matters'),
  ('niamh', 'fontaines-starburster', 'saw {artist} go past. grand. here’s one from home. it sounds like a panic attack you can dance to.', 'well? was it too much. it’s meant to be too much'),
  ('zainab', 'mustafa-stay-alive', 'you were playing {title} while i waited for the bus. this one’s for your ride home, whenever that is.', 'hey. glad it landed. what do you listen to when it’s late'),
  ('sol', 'caribou-cant-do-without-you', '{title}, nice. this is for later, when you’re deciding whether to stay out. (go home. play this.)', 'ha, you took it. so did you stay out or go home'),
  ('amara', 'cdw-work', '{artist} at this hour? same wavelength. here’s one from down the road.', 'accepted. good. are you working nights too or is it just insomnia'),
  ('malik', 'bbng-time-moves-slow', 'you played {title}, so i’m guessing you’d like this. my dad says it’s the only new record he approves of.', 'there you go. what’s the oldest record you own. i’m keeping a list');
insert into app.rooms (user_id, doc, updated_at) values
  ('maren', '{"personId":"maren","theme":{"paper":"#F3C6D0","card":"#FFF6EC","ink":"#1D4B3A","accent":"#E5482B","highlight":"#FFE066","texture":"grid","displayFont":"poster","wall":"scatter","layout":"loose"},"sections":[{"kind":"intro","title":"three songs, if we’ve never met","songs":[{"trackId":"big-thief-not","why":"the one I’d play to explain myself. it doesn’t, but it’s loud."},{"trackId":"alvvays-archie","why":"the one that makes me insufferable at weddings."},{"trackId":"joni-a-case-of-you","why":"the one I’m not ready to talk about."}],"stickers":[{"kind":"star","color":"#FFE066","x":0.86,"y":-0.06,"size":54,"rotate":14}]},{"kind":"pinned","title":"the pinned record","trackId":"bss-anthems","note":"Grade 10. Back seat of my cousin’s Corolla, the 401, somewhere past Pickering. She said “you’re not ready for this one” and she was right, and I’ve been not ready ever since.","stickers":[{"kind":"heart","color":"#E5482B","x":0.02,"y":0.7,"size":40,"rotate":-12}]},{"kind":"wall","title":"the wall","trackIds":["yo-la-tengo-autumn-sweater","feist-mushaboom","alex-g-runner","phoebe-motion-sickness","wednesday-chosen-to-deserve","mj-lenderman-shes-leaving-you","sufjan-chicago","nick-drake-pink-moon","elliott-between-the-bars"],"stickers":[{"kind":"burst","color":"#FFE066","x":0.7,"y":0.52,"size":78,"rotate":-10,"label":"no\nskips"},{"kind":"eye","color":"#FFF6EC","x":0.27,"y":0.26,"size":40,"rotate":8}]},{"kind":"shelf","title":"albums for the walk home","trackIds":["bon-iver-holocene","nick-drake-pink-moon","big-thief-simulation-swarm","yo-la-tengo-autumn-sweater","feist-mushaboom"]},{"kind":"liner","title":"liner notes","notes":[{"trackId":"wednesday-chosen-to-deserve","text":"Every verse is a confession you’d only make to someone who has already decided to stay. Also, it rips."},{"text":"Unpopular: the best seat at Massey Hall is the bad one behind the pillar. You have to lean. Leaning is commitment."},{"trackId":"mj-lenderman-shes-leaving-you","text":"He sounds like a man apologising at a barbecue. Five stars."}]},{"kind":"shelf","title":"songs i can only listen to after midnight","trackIds":["elliott-between-the-bars","mitski-my-love-mine","radiohead-weird-fishes","joni-a-case-of-you"],"stickers":[{"kind":"flower","color":"#FFF6EC","x":0.84,"y":-0.12,"size":44,"rotate":20}]},{"kind":"guestbook","title":"guestbook","entries":[{"fromId":"callum","trackId":"pup-kids","why":"you need to be yelled at. lovingly. three minutes, you’ll be fine."},{"fromId":"hana","trackId":"cocteau-heaven-or-las-vegas","why":"for the streetcar. window seat. do not look at your phone once."},{"fromId":"tobi","trackId":"badu-didnt-cha-know","why":"you said you “don’t really do neo-soul.” respectfully: start here."}]},{"kind":"recent","title":"recently played","visibility":"shown","trackIds":["big-thief-vampire-empire","alvvays-belinda-says","jbrekkie-be-sweet","bss-anthems"]}]}'::jsonb, app.now_ms()),
  ('dev', '{"personId":"dev","theme":{"paper":"#1B2559","card":"#243070","ink":"#F4EBD6","accent":"#FF7A59","highlight":"#3D5BD9","texture":"dots","displayFont":"typeBold","wall":"grid","layout":"pages"},"sections":[{"kind":"pinned","title":"PINNED","trackId":"burial-archangel","note":"Night bus, 2 a.m., Dufferin and Bloor, rain on the window doing half the work. I missed my stop on purpose and walked back."},{"kind":"liner","title":"NOTES FROM THE BOOTH","notes":[{"trackId":"steely-dan-peg","text":"Seven guitarists tried that solo before they kept one. I think about the other six a lot."},{"text":"If your favourite album was mastered loud, I don’t think less of you. I think less of the album."},{"trackId":"aphex-avril-14th","text":"You can hear the piano’s mechanism clunking. He left it in. That’s the whole lesson."}],"stickers":[{"kind":"bolt","color":"#FF7A59","x":0.86,"y":-0.08,"size":46,"rotate":12}]},{"kind":"intro","title":"START HERE","songs":[{"trackId":"mk-gee-are-you-looking-up","why":"sounds like a cassette of a song that hasn’t been written yet."},{"trackId":"madvillain-all-caps","why":"two minutes ten. not a second wasted. take notes, everyone."},{"trackId":"aphex-avril-14th","why":"for when I need to remember I’m a person."}]},{"kind":"shelf","title":"SONGS THAT SOUND LIKE FLUORESCENT LIGHTS","trackIds":["boc-roygbiv","burial-archangel","four-tet-baby","stereolab-french-disko"]},{"kind":"wall","title":"MIXES I’D DEFEND IN COURT","trackIds":["steely-dan-peg","sade-no-ordinary-love","dangelo-lady","talking-heads-this-must-be","fleetwood-everywhere","tribe-electric-relaxation"],"stickers":[{"kind":"smile","color":"#FFD23F","x":0.74,"y":0.74,"size":56,"rotate":-14}]},{"kind":"guestbook","title":"GUESTBOOK","entries":[{"fromId":"sol","trackId":"caribou-cant-do-without-you","why":"you need one (1) song that builds for no reason other than joy. prescription."},{"fromId":"wren","trackId":"bill-evans-peace-piece","why":"two chords for six minutes. I know you’ll respect the restraint."}]},{"kind":"recent","title":"RECENTLY PLAYED","visibility":"hidden","trackIds":[]}]}'::jsonb, app.now_ms()),
  ('tobi', '{"personId":"tobi","theme":{"paper":"#1F4034","card":"#2A5244","ink":"#F3E9D2","accent":"#F2A541","highlight":"#356B58","texture":"grain","displayFont":"serifBlack","wall":"grid","layout":"loose"},"sections":[{"kind":"pinned","title":"the one","trackId":"fela-water-no-get-enemy","note":"My dad’s Camry, 1998, somewhere on the QEW. He turned it up at the horns and said “this is your inheritance.” There was no other inheritance.","stickers":[{"kind":"star","color":"#356B58","x":0.8300000000000001,"y":-0.1,"size":60,"rotate":-3}]},{"kind":"intro","title":"start here, then we can talk","songs":[{"trackId":"fela-water-no-get-enemy","why":"eleven minutes. that’s the entry fee."},{"trackId":"burna-last-last","why":"for the walk to the gym, when i’m lying to myself about leg day."},{"trackId":"badu-didnt-cha-know","why":"proof i have a soft side. tell no one."}]},{"kind":"wall","title":"records i’d save in a fire","trackIds":["fela-water-no-get-enemy","burna-last-last","tems-free-mind","badu-didnt-cha-know","kaytranada-10-percent","kendrick-money-trees","death-grips-get-got","sade-no-ordinary-love","dangelo-lady"],"stickers":[{"kind":"burst","color":"#FFD23F","x":0.78,"y":0.48,"size":66,"rotate":-15}]},{"kind":"shelf","title":"songs that add ten pounds to the bar","trackIds":["burna-last-last","kaytranada-10-percent","kendrick-money-trees","death-grips-get-got"]},{"kind":"liner","title":"thoughts between sets","notes":[{"trackId":"fela-water-no-get-enemy","text":"People say they don’t have time for a long song, then watch a man build a swimming pool on their phone for four hours."},{"text":"The gym playlist is not a democracy and it is not a suggestion box."}]},{"kind":"shelf","title":"sunday, windows open","trackIds":["tems-free-mind","sade-no-ordinary-love","badu-didnt-cha-know","dangelo-lady"]},{"kind":"guestbook","title":"sign here","entries":[{"fromId":"amara","trackId":"cdw-work","why":"toronto made this. be proud for four minutes."},{"fromId":"ingrid","tra