  ('priya', '{"personId":"priya","theme":{"paper":"#F6A04D","card":"#FFF0D6","ink":"#1F2A6B","accent":"#C9391C","highlight":"#FFE066","texture":"grain","displayFont":"poster","wall":"scatter","layout":"loose"},"sections":[{"kind":"intro","title":"three songs. no skipping.","songs":[{"trackId":"ap-dhillon-brown-munde","why":"the one that took over every car in brampton for a year."},{"trackId":"diljit-goat","why":"the one my mom and i agree on. the only one."},{"trackId":"drake-passionfruit","why":"the one for when i pretend i’m from toronto proper."}],"stickers":[{"kind":"heart","color":"#FFD23F","x":0.8200000000000001,"y":-0.09000000000000001,"size":71,"rotate":8}]},{"kind":"pinned","title":"the one","trackId":"sidhu-295","note":"Summer 2021, my cousin’s Civic outside the plaza on Airport Road. Windows down, everybody quiet for once. I didn’t know a song could do that to a parking lot."},{"kind":"shelf","title":"wedding bangers, ranked by aunty approval","trackIds":["diljit-goat","ap-dhillon-brown-munde","shania-man-i-feel","abba-dancing-queen"],"stickers":[{"kind":"bolt","color":"#FFE066","x":0.8400000000000001,"y":-0.1,"size":53,"rotate":12}]},{"kind":"wall","title":"on the wall","trackIds":["sidhu-295","ap-dhillon-brown-munde","diljit-goat","drake-passionfruit","shania-man-i-feel","abba-dancing-queen"],"stickers":[{"kind":"star","color":"#C9391C","x":0.5900000000000001,"y":0.54,"size":51,"rotate":-8}]},{"kind":"liner","title":"rules of the aux","notes":[{"text":"Rule one: ask “who is this?” in a good way and you get a turn. Ask it in a bad way and you get the bus."},{"trackId":"sidhu-295","text":"He wrote it like he knew. I still can’t get through the last verse in public."}]},{"kind":"shelf","title":"the drive home from the reception","trackIds":["sidhu-295","drake-passionfruit","weeknd-house-of-balloons"]},{"kind":"guestbook","title":"guestbook","entries":[{"fromId":"eli","trackId":"pavement-gold-soundz","why":"staff pick, every week, until someone stops me. n