  ('callum', '{"personId":"callum","theme":{"paper":"#E5482B","card":"#F26A4F","ink":"#FFF3DE","accent":"#FFD23F","highlight":"#B5301E","texture":"dots","displayFont":"poster","wall":"scatter","layout":"poster"},"sections":[{"kind":"pinned","title":"pinned","trackId":"pup-kids","note":"Lee’s Palace. The floor was mostly beer. Somebody’s elbow got me in the first chorus and I have never been happier. Lost a shoe. Kept the ticket.","stickers":[{"kind":"bolt","color":"#FFD23F","x":0.81,"y":-0.1,"size":70,"rotate":-12}]},{"kind":"wall","title":"the wall","trackIds":["pup-kids","fucked-up-queen-of-hearts","turnstile-mystery","title-fight-head-in-the-ceiling-fan","mcr-helena","deftones-be-quiet"],"stickers":[{"kind":"star","color":"#FFD23F","x":0.63,"y":0.54,"size":68,"rotate":4}]},{"kind":"intro","title":"if you’ve only got nine minutes","songs":[{"trackId":"pup-kids","why":"the happiest song ever written about wanting to lie down in traffic."},{"trackId":"fucked-up-queen-of-hearts","why":"toronto, a choir, a man yelling. what else is there."},{"trackId":"turnstile-mystery","why":"hardcore for people who also want to dance. so, everyone."}]},{"kind":"shelf","title":"for the back of the line (kitchen)","trackIds":["title-fight-head-in-the-ceiling-fan","mcr-helena","deftones-be-quiet","paramore-hard-times"]},{"kind":"liner","title":"notes from the pit","notes":[{"text":"Etiquette: somebody falls, everybody picks them up. That’s the whole religion."},{"trackId":"mcr-helena","text":"I was fourteen and it was the most important thing that had ever happened. It still might be."}]},{"kind":"shelf","title":"gang vocals, sorted by how hoarse i got","trackIds":["pup-kids","fucked-up-queen-of-hearts","turnstile-mystery","american-football-never-meant"]},{"kind":"guestbook","title":"visitors’ book","entries":[{"fromId":"ingrid","trackId":"alice-coltrane-satchidananda","why":"the harp comes in and the lake goes flat. i’ve tested this."},{"fromId":"sol","trackId":"caribou-cant-do-with