  ('hana', '{"personId":"hana","theme":{"paper":"#D5C8F0","card":"#F6F1FF","ink":"#1F3D2B","accent":"#D94F30","highlight":"#FFE066","texture":"grain","displayFont":"poster","wall":"scatter","layout":"loose"},"sections":[{"kind":"intro","title":"three songs, played too loud","songs":[{"trackId":"slowdive-when-the-sun-hits","why":"the one that sounds like the inside of a cloud."},{"trackId":"mbv-only-shallow","why":"the one that made me buy a pedal i can’t afford."},{"trackId":"cocteau-heaven-or-las-vegas","why":"the one where the words don’t matter. they never did."}],"stickers":[{"kind":"star","color":"#FFD23F","x":0.8500000000000001,"y":-0.05,"size":55,"rotate":-17}]},{"kind":"wall","title":"the wall","trackIds":["slowdive-when-the-sun-hits","mbv-only-shallow","cocteau-heaven-or-las-vegas","deftones-be-quiet","cure-just-like-heaven","yo-la-tengo-autumn-sweater"],"stickers":[{"kind":"heart","color":"#FFE066","x":0.63,"y":0.5900000000000001,"size":53,"rotate":-1}]},{"kind":"pinned","title":"pinned","trackId":"slowdive-when-the-sun-hits","note":"Grade 11, my brother’s burned CD, the bus up Yonge in a snowstorm. The windows fogged over and I decided this was who I was now. It was."},{"kind":"shelf","title":"pedals i bought because of a song","trackIds":["mbv-only-shallow","slowdive-when-the-sun-hits","deftones-be-quiet","cure-just-like-heaven"]},{"kind":"liner","title":"said into a wall of reverb","notes":[{"trackId":"mbv-only-shallow","text":"People ask what the lyrics are. I’ve listened for nine years. I don’t know. I don’t want to know."},{"text":"My amp is too big for my apartment. That’s the apartment’s problem."}]},{"kind":"shelf","title":"for when the heat’s broken","trackIds":["cocteau-heaven-or-las-vegas","yo-la-tengo-autumn-sweater","boc-roygbiv"]},{"kind":"guestbook","title":"sign here","entries":[{"fromId":"bea","trackId":"feist-mushaboom","why":"i want the life in this song so badly it’s embarrassing."},{"fromId":"priya","trackId":"sidhu-295","why":"if you