  ('sol', '{"personId":"sol","theme":{"paper":"#BFE5D2","card":"#F4FBF6","ink":"#3A1F4D","accent":"#E5482B","highlight":"#FFE066","texture":"dots","displayFont":"poster","wall":"grid","layout":"loose"},"sections":[{"kind":"intro","title":"three for the pregame (it’s also the main event)","songs":[{"trackId":"peggy-gou-nanana","why":"the one where everybody knows the hook by the second time round."},{"trackId":"kaytranada-10-percent","why":"the one that works at brunch and at 11 p.m. rare."},{"trackId":"four-tet-baby","why":"the one for the ride home, forehead on the window."}],"stickers":[{"kind":"star","color":"#FFE066","x":0.8200000000000001,"y":-0.08,"size":71,"rotate":-17}]},{"kind":"pinned","title":"pinned","trackId":"caribou-cant-do-without-you","note":"A basement off Geary, 1:10 a.m. I’d already put my coat on to leave. Then this came on and I took the coat off again. Only time that’s ever happened."},{"kind":"shelf","title":"club music for people with a 9 a.m.","trackIds":["peggy-gou-nanana","kaytranada-10-percent","charli-von-dutch","caribou-cant-do-without-you"]},{"kind":"wall","title":"records i’d save in a fire","trackIds":["peggy-gou-nanana","caribou-cant-do-without-you","four-tet-baby","kaytranada-10-percent","charli-von-dutch","sade-no-ordinary-love"],"stickers":[{"kind":"burst","color":"#FFD23F","x":0.56,"y":0.61,"size":55,"rotate":7}]},{"kind":"liner","title":"a manifesto, sort of","notes":[{"text":"Leaving at one isn’t giving up. It’s leaving while you still love everyone."},{"trackId":"charli-von-dutch","text":"I can’t hear this without walking faster. It’s a safety issue."}]},{"kind":"shelf","title":"kitchen, sunday, eggs","trackIds":["four-tet-baby","sade-no-ordinary-love","fleetwood-everywhere"]},{"kind":"guestbook","title":"guestbook","entries":[{"fromId":"grace","trackId":"glenn-gould-aria","why":"you can hear him humming along. his engineers hated it. it’s my favourite part."},{"fromId":"rohan","trackId":"lcd-all-my-friends","why":"seven minutes about getting older. i was 22 when i first cried at it. why."},{"fromId":"wren","trackId":"bill-evans-peace-piece","why":"six minutes. put the phone down. (you’re holding the phone. i know.)"}]},{"kind":"recent","title":"lately","visibility":"shown","trackIds":["peggy-gou-nanana","caribou-cant-do-without-you","four-tet-baby","kaytranada-10-percent"]}]}'::jsonb, app.now_ms()),
  ('wren', '{"personId":"wren","theme":{"paper":"#FBFAF4","card":"#FFFFFF","ink":"#23308C","accent":"#D7263D","highlight":"#FFF07A","texture":"ruled","displayFont":"hand","wall":"grid","layout":"loose"},"sections":[{"kind":"pinned","title":"pinned","trackId":"bill-evans-peace-piece","note":"A practice room at the Conservatory, nineteen, hiding from my own recital. Someone played this next door, through the wall. I stayed for all of it and was late for my slot.","stickers":[{"kind":"eye","color":"#FFD23F","x":0.8700000000000001,"y":-0.07,"size":54,"rotate":-1}]},{"kind":"intro","title":"three pieces of evidence","songs":[{"trackId":"bill-evans-peace-piece","why":"exhibit a: restraint."},{"trackId":"miles-so-what","why":"exhibit b: two chords is plenty."},{"trackId":"nickelback-how-you-remind-me","why":"exhibit c: i’m from alberta and you’ll have to live with it."}]},{"kind":"liner","title":"margin notes","notes":[{"trackId":"glenn-gould-aria","text":"He hums. Everybody mentions it. Nobody mentions that he’s in tune."},{"trackId":"nickelback-how-you-remind-me","text":"I have a degree in music and I’m telling you the chorus resolves properly. That’s all I’ll say."}]},{"kind":"shelf","title":"for students who say they hate jazz","trackIds":["miles-so-what","bill-evans-peace-piece","nina-sinnerman","bbng-time-moves-slow"]},{"kind":"wall","title":"the wall","trackIds":["bill-evans-peace-piece","miles-so-what","alice-coltrane-satchidananda","glenn-gould-aria","nickelback-how-you-remind-me","nina-sinnerman"],"stickers":[{"kind":"bolt","color":"#FFF07A","x":0.7000000000000001,"y":0.69,"size":52,"rotate":15}]},{"kind":"shelf","title":"after the last lesson of the day","trackIds":["alice-coltrane-satchidananda","glenn-gould-aria","aphex-avril-14th"]},{"kind":"guestbook","title":"sign here","entries":[{"fromId":"jamal","trackId":"death-grips-get-got","why":"this is the one that got me banned. i regret nothing."},{"fromId":"tessa","trackId":"cameron-winter-love-takes-miles","why":"he sings like he’s remembering the words as they arrive. cited in my thesis (it isn’t)."},{"fromId":"marisol","trackId":"shania-man-i-feel","why":"first three notes and the whole bar stands up. that’s power. timmins, ontario."}]},{"kind":"recent","title":"lately","visibility":"shown","trackIds":["bill-evans-peace-piece","miles-so-what","alice-coltrane-satchidananda","glenn-gould-aria"]}]}'::jsonb, app.now_ms()),
