  ('jonah', '{"personId":"jonah","theme":{"paper":"#DCD8CC","card":"#F3F0E6","ink":"#1E1E1E","accent":"#B3261E","highlight":"#F2D94E","texture":"grain","displayFont":"serifBlack","wall":"grid","layout":"pages"},"sections":[{"kind":"liner","title":"liner notes on liner notes","notes":[{"trackId":"steely-dan-peg","text":"Seven guitarists attempted the solo. Jay Graydon got it. I think about the other six more than is healthy."},{"text":"A hi-fi is not a midlife crisis. A midlife crisis would have been cheaper."}],"stickers":[{"kind":"burst","color":"#B3261E","x":0.8400000000000001,"y":-0.08,"size":63,"rotate":-16}]},{"kind":"pinned","title":"the one","trackId":"steely-dan-peg","note":"My father’s den in Thornhill, 1994. I wasn’t allowed to touch the turntable, so I watched. He lowered the needle like he was defusing something."},{"kind":"intro","title":"a brief introduction (four pages)","songs":[{"trackId":"steely-dan-peg","why":"start here. yes, there’s a quiz."},{"trackId":"talking-heads-this-must-be","why":"the only love song without a single cliché in it. i checked."},{"trackId":"destroyer-kaputt","why":"vancouver’s finest. sounds like a yacht with a library on it."}]},{"kind":"wall","title":"records i’d save in a fire","trackIds":["steely-dan-peg","talking-heads-this-must-be","fleetwood-everywhere","lcd-all-my-friends","destroyer-kaputt","sade-no-ordinary-love"],"stickers":[{"kind":"heart","color":"#F2D94E","x":0.67,"y":0.67,"size":69,"rotate":8}]},{"kind":"shelf","title":"records my wife has asked me to stop explaining","trackIds":["steely-dan-peg","fleetwood-everywhere","talking-heads-this-must-be","destroyer-kaputt"]},{"kind":"shelf","title":"acceptable at dinner parties","trackIds":["sade-no-ordinary-love","lcd-all-my-friends","bbng-time-moves-slow"]},{"kind":"guestbook","title":"visitors’ book","entries":[{"fromId":"mateo","trackId":"bad-bunny-titi","why":"wait for the switch-up. no, keep waiting. THERE."},{"fromId":"yuki","trackId":"crj-run-away-with-me","