  ('malik', '{"personId":"malik","theme":{"paper":"#D9B88A","card":"#EFE2C6","ink":"#2B211B","accent":"#B5301E","highlight":"#F3E3A2","texture":"dots","displayFont":"typeBold","wall":"grid","layout":"loose"},"sections":[{"kind":"wall","title":"RECORDS I’D SAVE IN A FIRE","trackIds":["tribe-electric-relaxation","madvillain-all-caps","dangelo-lady","badu-didnt-cha-know","kendrick-money-trees","bbng-time-moves-slow"],"stickers":[{"kind":"bolt","color":"#FFD23F","x":0.6900000000000001,"y":0.51,"size":65,"rotate":-5}]},{"kind":"pinned","title":"THE ONE","trackId":"tribe-electric-relaxation","note":"My dad’s basement on Oakwood. I was nine and banned from the crates. He caught me holding this one and instead of yelling he said, “Fine. Flip it over.”"},{"kind":"intro","title":"three from the crates","songs":[{"trackId":"tribe-electric-relaxation","why":"the first one i was allowed to touch."},{"trackId":"madvillain-all-caps","why":"the first one i bought with my own money."},{"trackId":"bbng-time-moves-slow","why":"the first new one my dad nodded at."}]},{"kind":"liner","title":"sleeve notes","notes":[{"text":"Four hundred records and he filed them by how he felt that year. I’ve given up re-sorting."},{"trackId":"dangelo-lady","text":"The drums are late on purpose. Try explaining that to a metronome."}]},{"kind":"shelf","title":"dad’s records (do not lend)","trackIds":["tribe-electric-relaxation","dangelo-lady","badu-didnt-cha-know","miles-so-what"]},{"kind":"shelf","title":"mine (also do not lend)","trackIds":["madvillain-all-caps","kendrick-money-trees","bbng-time-moves-slow","frank-ocean-pink-white"]},{"kind":"guestbook","title":"GUESTBOOK","entries":[{"fromId":"hyejin","trackId":"yo-la-tengo-autumn-sweater","why":"an organ, a drum loop and a feeling. nobody has topped it since 1997."},{"fromId":"dev","trackId":"boc-roygbiv","why":"two and a half minutes. headphones, not the phone speaker. i’ll know."},{"fromId":"mateo","trackId":"bad-bunny-titi","why":"wait for the swi