  ('sofia', '{"personId":"sofia","theme":{"paper":"#F9E26B","card":"#FFF9D9","ink":"#1B1B1B","accent":"#D7263D","highlight":"#FFFFFF","texture":"dots","displayFont":"poster","wall":"grid","layout":"loose"},"sections":[{"kind":"intro","title":"three for the salon speaker","songs":[{"trackId":"charli-von-dutch","why":"monday. everybody needs it."},{"trackId":"chappell-good-luck-babe","why":"the one clients ask me to play again."},{"trackId":"abba-dancing-queen","why":"closing time. non-negotiable."}],"stickers":[{"kind":"heart","color":"#FFFFFF","x":0.8400000000000001,"y":-0.05,"size":55,"rotate":-4}]},{"kind":"pinned","title":"the one","trackId":"abba-dancing-queen","note":"Nonna’s kitchen in Woodbridge, me on a chair so I could reach the radio. She said it was noise. She was also dancing. She denies this."},{"kind":"shelf","title":"songs that got a client to finally go blonde","trackIds":["chappell-good-luck-babe","charli-von-dutch","peggy-gou-nanana","paramore-hard-times"]},{"kind":"wall","title":"records i’d save in a fire","trackIds":["charli-von-dutch","chappell-good-luck-babe","abba-dancing-queen","peggy-gou-nanana","paramore-hard-times","celine-all-coming-back"],"stickers":[{"kind":"eye","color":"#FFD23F","x":0.6900000000000001,"y":0.7,"size":61,"rotate":-16}]},{"kind":"liner","title":"overheard at the chair","notes":[{"text":"You learn everything about a person from what they hum under the dryer."},{"trackId":"paramore-hard-times","text":"Saddest lyrics, happiest song. That’s a haircut after a breakup."}]},{"kind":"shelf","title":"nonna-approved (short shelf)","trackIds":["abba-dancing-queen","celine-all-coming-back"]},{"kind":"guestbook","title":"guestbook","entries":[{"fromId":"mateo","trackId":"bad-bunny-titi","why":"wait for the switch-up. no, keep waiting. THERE."},{"fromId":"lucia","trackId":"beaches-blame-brett","why":"named after the neighbourhood, not the lake. saw them at the horseshoe before all this."},{"fromId":"tessa","trackId":"cameron-winter-l