  ('dez', '{"personId":"dez","theme":{"paper":"#A9DDE6","card":"#F1FBFD","ink":"#14305A","accent":"#F0502F","highlight":"#FFE066","texture":"grid","displayFont":"serifBlack","wall":"grid","layout":"loose"},"sections":[{"kind":"pinned","title":"the one","trackId":"miles-so-what","note":"A wedding in Vaughan, 1 a.m., the band packing up. The drummer put this on the house speakers and none of us left for nine minutes. Unpaid overtime. Worth it.","stickers":[{"kind":"eye","color":"#F0502F","x":0.8200000000000001,"y":-0.05,"size":62,"rotate":12}]},{"kind":"intro","title":"three basslines, since nobody asks","songs":[{"trackId":"miles-so-what","why":"paul chambers. the whole song is his."},{"trackId":"dangelo-lady","why":"pino. behind the beat. on purpose."},{"trackId":"bbng-time-moves-slow","why":"local, and it walks."}]},{"kind":"wall","title":"on the wall","trackIds":["bbng-time-moves-slow","miles-so-what","steely-dan-peg","dangelo-lady","fela-water-no-get-enemy","abba-dancing-queen","shania-man-i-feel","celine-all-coming-back","bill-evans-peace-piece"],"stickers":[{"kind":"burst","color":"#FFD23F","x":0.6200000000000001,"y":0.71,"size":65,"rotate":-4}]},{"kind":"liner","title":"notes from stage left","notes":[{"text":"Nobody notices the bass until it stops. Then everybody’s a critic."},{"trackId":"fela-water-no-get-enemy","text":"The bassline doesn’t change for eleven minutes, and that is the hardest thing in music."}]},{"kind":"shelf","title":"requests i play under protest","trackIds":["abba-dancing-queen","shania-man-i-feel","celine-all-coming-back"]},{"kind":"shelf","title":"what the trio plays when it’s just the bartender","trackIds":["miles-so-what","bill-evans-peace-piece","alice-coltrane-satchidananda","steely-dan-peg"]},{"kind":"guestbook","title":"visitors’ book","entries":[{"fromId":"sol","trackId":"caribou-cant-do-without-you","why":"one line, repeated, and somehow i’m crying at a bus stop. dundas, ontario did this."},{"fromId":"lucia","trackId":"beaches-bl