  ('ingrid', '{"personId":"ingrid","theme":{"paper":"#DDE5E4","card":"#F4F7F5","ink":"#2B3A42","accent":"#C6533A","highlight":"#BFD9D2","texture":"grain","displayFont":"serifBlack","wall":"grid","layout":"pages"},"sections":[{"kind":"pinned","title":"the pinned record","trackId":"aphex-avril-14th","note":"The boardwalk in February, nobody else out, the lake the colour of a nickel. It’s two minutes long. I played it eleven times and walked to the end and back.","stickers":[{"kind":"eye","color":"#BFD9D2","x":0.8600000000000001,"y":-0.07,"size":71,"rotate":-11}]},{"kind":"liner","title":"field notes","notes":[{"text":"Ambient music isn’t background. You’re the background."},{"trackId":"burial-archangel","text":"It sounds like rain remembering a nightclub."}]},{"kind":"intro","title":"three, quietly","songs":[{"trackId":"aphex-avril-14th","why":"a piano with the lid open. you can hear the room."},{"trackId":"boc-roygbiv","why":"sounds like a science film from a school that closed."},{"trackId":"alice-coltrane-satchidananda","why":"the harp comes in and the lake goes flat."}],"stickers":[{"kind":"star","color":"#FFD23F","x":0.8400000000000001,"y":-0.060000000000000005,"size":67,"rotate":-15}]},{"kind":"shelf","title":"one album a day (this week)","trackIds":["burial-archangel","boc-roygbiv","cocteau-heaven-or-las-vegas","aphex-avril-14th"]},{"kind":"wall","title":"the good wall","trackIds":["aphex-avril-14th","boc-roygbiv","burial-archangel","alice-coltrane-satchidananda","cocteau-heaven-or-las-vegas","mbv-only-shallow"],"stickers":[{"kind":"heart","color":"#C6533A","x":0.73,"y":0.7,"size":64,"rotate":1}]},{"kind":"shelf","title":"too loud for the boardwalk","trackIds":["mbv-only-shallow","slowdive-when-the-sun-hits"]},{"kind":"guestbook","title":"guestbook","entries":[{"fromId":"sofia","trackId":"abba-dancing-queen","why":"not ironically. never ironically."},{"fromId":"amara","trackId":"cdw-work","why":"toronto made this. be proud for four minutes."}]},{"kind":"recent"