  ('mateo', '{"personId":"mateo","theme":{"paper":"#FFC857","card":"#FFF0D6","ink":"#1F2A6B","accent":"#C9391C","highlight":"#FFE066","texture":"dots","displayFont":"serifBlack","wall":"scatter","layout":"poster"},"sections":[{"kind":"intro","title":"three for the chair","songs":[{"trackId":"bad-bunny-titi","why":"wait for the switch. no, keep waiting."},{"trackId":"kaytranada-10-percent","why":"makes anyone sit up straight. good for the neckline."},{"trackId":"drake-passionfruit","why":"for the clients who want to feel something but not say it."}],"stickers":[{"kind":"heart","color":"#C9391C","x":0.8200000000000001,"y":-0.05,"size":66,"rotate":4}]},{"kind":"pinned","title":"pinned","trackId":"bad-bunny-titi","note":"The shop on St. Clair, a Saturday, six guys waiting. It came on and the whole line started arguing about the switch-up. I gave the worst fade of my career. No regrets."},{"kind":"shelf","title":"saturdays, wall to wall","trackIds":["bad-bunny-titi","peggy-gou-nanana","kaytranada-10-percent","burna-last-last"]},{"kind":"wall","title":"records i’d save in a fire","trackIds":["bad-bunny-titi","peggy-gou-nanana","kaytranada-10-percent","drake-passionfruit","burna-last-last"],"stickers":[{"kind":"eye","color":"#FFE066","x":0.68,"y":0.53,"size":51,"rotate":-8}]},{"kind":"liner","title":"barber’s notes","notes":[{"text":"Salsa is what my parents danced to. Perreo is what I danced to. One day my kids will embarrass me with something worse."},{"trackId":"peggy-gou-nanana","text":"Nobody knows what the chorus means and the whole shop sings it anyway."}]},{"kind":"guestbook","title":"visitors’ book","entries":[{"fromId":"grace","trackId":"glenn-gould-aria","why":"you can hear him humming along. his engineers hated it. it’s my favourite part."},{"fromId":"callum","trackId":"fucked-up-queen-of-hearts","why":"toronto’s finest. a children’s choir and a man yelling. perfect song."},{"fromId":"dev","trackId":"boc-roygbiv","why":"two and a half minutes. headphones, not t