  ('theo', '{"personId":"theo","theme":{"paper":"#F2F0E6","card":"#FFFFFF","ink":"#161616","accent":"#E5262B","highlight":"#FFE600","texture":"dots","displayFont":"typeBold","wall":"scatter","layout":"poster"},"sections":[{"kind":"intro","title":"THREE SONGS FROM THE FREEZER","songs":[{"trackId":"mcr-helena","why":"i was fourteen. i’m still fourteen."},{"trackId":"american-football-never-meant","why":"the house on the cover. you know the one."},{"trackId":"title-fight-head-in-the-ceiling-fan","why":"for lying on the floor. try it."}],"stickers":[{"kind":"flower","color":"#FFD23F","x":0.8500000000000001,"y":-0.060000000000000005,"size":58,"rotate":-10}]},{"kind":"pinned","title":"PINNED","trackId":"mcr-helena","note":"The walk-in freezer at my uncle’s place on the Danforth, 2009. I was supposed to be getting lamb. I stayed for the whole song and came out with frost on my eyebrows."},{"kind":"wall","title":"RECORDS I’D SAVE IN A FIRE","trackIds":["mcr-helena","american-football-never-meant","title-fight-head-in-the-ceiling-fan","paramore-hard-times","pup-kids","elliott-between-the-bars"],"stickers":[{"kind":"star","color":"#FFFFFF","x":0.63,"y":0.5700000000000001,"size":64,"rotate":14}]},{"kind":"shelf","title":"EMO NIGHT, FIRST HALF","trackIds":["mcr-helena","paramore-hard-times","pup-kids","american-football-never-meant"]},{"kind":"liner","title":"KITCHEN CONFESSIONS","notes":[{"text":"Two emo nights survived. At the second one a teenager called me “sir.”"},{"trackId":"paramore-hard-times","text":"She made a disco song about being miserable and I’ve never felt so understood by a tambourine."}]},{"kind":"shelf","title":"EMO NIGHT, AFTER MY KNEES GAVE OUT","trackIds":["title-fight-head-in-the-ceiling-fan","elliott-between-the-bars","deftones-be-quiet"]},{"kind":"guestbook","title":"GUESTBOOK","entries":[{"fromId":"niamh","trackId":"fontaines-starburster","why":"the gasp between lines is the hook. dubliners, obviously."},{"fromId":"tessa","trackId":"cameron-winter-love-takes-miles","why":"he sings like he’s remembering the words as they arrive. cited in my thesis (it isn’t)."},{"fromId":"rohan","trackId":"lcd-all-my-friends","why":"seven minutes about getting older. i was 22 when i first cried at it. why."}]},{"kind":"recent","title":"LATELY","visibility":"shown","trackIds":["mcr-helena","american-football-never-meant","title-fight-head-in-the-ceiling-fan","paramore-hard-times"]}]}'::jsonb, app.now_ms()),
  ('grace', '{"personId":"grace","theme":{"paper":"#FBF8F0","card":"#FFFFFF","ink":"#23308C","accent":"#3A6EA5","highlight":"#FFF07A","texture":"ruled","displayFont":"serifBlack","wall":"grid","layout":"pages"},"sections":[{"kind":"pinned","title":"the one","trackId":"glenn-gould-aria","note":"An exam room, fourteen, waiting to play for three strangers with clipboards. My teacher had told me to listen to this the night before. I listened in the hallway instead and played better than I ever had.","stickers":[{"kind":"flower","color":"#FFD23F","x":0.8500000000000001,"y":-0.060000000000000005,"size":54,"rotate":-10}]},{"kind":"intro","title":"three things i’m allowed to like now","songs":[{"trackId":"radiohead-weird-fishes","why":"the first non-classical thing i loved. i felt like i was cheating."},{"trackId":"sufjan-chicago","why":"i played the trumpet part on piano for a year."},{"trackId":"nina-sinnerman","why":"ten minutes. she never lets up. neither should you."}]},{"kind":"liner","title":"practice log","notes":[{"trackId":"glenn-gould-aria","text":"You can hear him humming along. His engineers hated it. It’s my favourite part."},{"text":"Nobody tells you that when the exams stop, you have to decide what you like on your own. I’m 26 and still deciding."}]},{"kind":"shelf","title":"fourteen years of piano exams","trackIds":["glenn-gould-aria","bill-evans-peace-piece","nina-sinnerman","aphex-avril-14th"]},{"kind":"wall","title":"the wall","trackIds":["glenn-gould-aria","bill-evans-peace-piece","nina-sinnerman","radiohead-weird-fishes","sufjan-chicago","aphex-avril-14th"],"stickers":[{"kind":"burst","color":"#3A6EA5","x":0.77,"y":0.71,"size":52,"rotate":6}]},{"kind":"guestbook","title":"visitors’ book","entries":[{"fromId":"callum","trackId":"fucked-up-queen-of-hearts","why":"toronto’s finest. a children’s choir and a man yelling. perfect song."},{"fromId":"hana","trackId":"mbv-only-shallow","why":"turn it up until it stops being a song and becomes weather."},{"fromI