  ('niamh', '{"personId":"niamh","theme":{"paper":"#F2F0E6","card":"#FFFFFF","ink":"#161616","accent":"#E5262B","highlight":"#7CFFB2","texture":"grain","displayFont":"poster","wall":"scatter","layout":"loose"},"sections":[{"kind":"intro","title":"three before the kettle’s boiled","songs":[{"trackId":"fontaines-starburster","why":"the gasp between the lines is the hook."},{"trackId":"bcnr-the-place","why":"seven minutes and a whole room singing by the end."},{"trackId":"geese-taxes","why":"new york lads. they’ll do."}],"stickers":[{"kind":"bolt","color":"#FFD23F","x":0.8700000000000001,"y":-0.09000000000000001,"size":60,"rotate":10}]},{"kind":"pinned","title":"pinned","trackId":"fontaines-starburster","note":"The airport, the day I flew over. I had one bag and no flat. This came on in the queue and I thought, right, at least that’ll come with me."},{"kind":"wall","title":"the good wall","trackIds":["fontaines-starburster","bcnr-the-place","geese-taxes","cameron-winter-love-takes-miles","stereolab-french-disko","sonic-youth-teen-age-riot"],"stickers":[{"kind":"smile","color":"#7CFFB2","x":0.66,"y":0.56,"size":54,"rotate":-14}]},{"kind":"liner","title":"letters home","notes":[{"text":"Came for a year in 2019. Still can’t find a decent tea. Staying anyway."},{"trackId":"stereolab-french-disko","text":"A protest song you can do the dishes to. Very practical people, the French."}]},{"kind":"shelf","title":"post-punk, pre-coffee","trackIds":["fontaines-starburster","sonic-youth-teen-age-riot","stereolab-french-disko","geese-taxes"]},{"kind":"shelf","title":"songs that make parkdale feel like home","trackIds":["bcnr-the-place","cameron-winter-love-takes-miles","cure-just-like-heaven"]},{"kind":"guestbook","title":"sign here","entries":[{"fromId":"bea","trackId":"feist-mushaboom","why":"i want the life in this song so badly it’s embarrassing."},{"fromId":"andre","trackId":"sade-no-ordinary-love","why":"works at a wedding. works at a wake. that’s the test."}]},{"kind":"recent