  ('jamal', '{"personId":"jamal","theme":{"paper":"#F9E26B","card":"#FFF9D9","ink":"#1B1B1B","accent":"#1F2A6B","highlight":"#FFFFFF","texture":"dots","displayFont":"poster","wall":"scatter","layout":"poster"},"sections":[{"kind":"pinned","title":"the pinned record","trackId":"death-grips-get-got","note":"My cousin’s graduation barbecue, Brampton, 2019. I had the aux for four minutes. Went from Drake straight into this. Her grandmother left. I maintain the transition was good.","stickers":[{"kind":"bolt","color":"#FFFFFF","x":0.8200000000000001,"y":-0.060000000000000005,"size":54,"rotate":6}]},{"kind":"intro","title":"three songs i’m no longer allowed to play","songs":[{"trackId":"death-grips-get-got","why":"banned: the graduation barbecue."},{"trackId":"kendrick-money-trees","why":"banned: i did all the voices. at a christening."},{"trackId":"burna-last-last","why":"not banned. this one’s how i get the aux back."}]},{"kind":"wall","title":"the good wall","trackIds":["kendrick-money-trees","drake-passionfruit","burna-last-last","tems-free-mind","death-grips-get-got"],"stickers":[{"kind":"smile","color":"#1F2A6B","x":0.66,"y":0.47000000000000003,"size":70,"rotate":-18}]},{"kind":"shelf","title":"the redemption playlist","trackIds":["burna-last-last","tems-free-mind","drake-passionfruit","kendrick-money-trees"]},{"kind":"liner","title":"statements for the record","notes":[{"text":"The crowd was wrong. I’ve reviewed the tape."},{"trackId":"tems-free-mind","text":"Put this on and even the aunties forgive you. I’ve tested it."}]},{"kind":"guestbook","title":"guestbook","entries":[{"fromId":"yuki","trackId":"crj-run-away-with-me","why":"the saxophone at the start is a national treasure and we don’t say it enough."},{"fromId":"ingrid","trackId":"alice-coltrane-satchidananda","why":"the harp comes in and the lake goes flat. i’ve tested this."}]},{"kind":"recent","title":"recently played","visibility":"shown","trackIds":["kendrick-money-trees","drake-passionfruit","burna-las