  ('clemence', '{"personId":"clemence","theme":{"paper":"#DDE5E4","card":"#F4F7F5","ink":"#2B3A42","accent":"#2F5DA8","highlight":"#F7C6D0","texture":"grain","displayFont":"hand","wall":"scatter","layout":"loose"},"sections":[{"kind":"intro","title":"three songs, translated badly","songs":[{"trackId":"wolf-parade-ill-believe","why":"montréal, when it was cheap."},{"trackId":"stereolab-french-disko","why":"the french is fine. the politics are better."},{"trackId":"celine-all-coming-back","why":"a queen. i will not be taking questions in either language."}],"stickers":[{"kind":"bolt","color":"#FFD23F","x":0.8,"y":-0.08,"size":64,"rotate":0}]},{"kind":"pinned","title":"the pinned record","trackId":"wolf-parade-ill-believe","note":"A loft party in the Mile End, 2006, the floor actually bending. Everyone I knew was in one room. I moved here eight years later and I still measure parties against that one."},{"kind":"shelf","title":"things montréal does better","trackIds":["wolf-parade-ill-believe","destroyer-kaputt","celine-all-coming-back"]},{"kind":"wall","title":"the wall","trackIds":["wolf-parade-ill-believe","stereolab-french-disko","caribou-cant-do-without-you","destroyer-kaputt","celine-all-coming-back","bss-anthems"],"stickers":[{"kind":"star","color":"#F7C6D0","x":0.63,"y":0.74,"size":62,"rotate":16}]},{"kind":"liner","title":"notes du traducteur","notes":[{"text":"I defend this city in French so that nobody here can hear me doing it."},{"trackId":"caribou-cant-do-without-you","text":"One sentence, repeated. As a translator I should hate it. I don’t."}]},{"kind":"shelf","title":"things toronto does better (short shelf)","trackIds":["caribou-cant-do-without-you","bss-anthems"]},{"kind":"guestbook","title":"guestbook","entries":[{"fromId":"eli","trackId":"pavement-gold-soundz","why":"staff pick, every week, until someone stops me. nobody has."},{"fromId":"tessa","trackId":"cameron-winter-love-takes-miles","why":"he sings like he’s remembering the words as they arriv