  ('lucia', '{"personId":"lucia","theme":{"paper":"#FFD8C2","card":"#FFF4EC","ink":"#5A2A27","accent":"#E5482B","highlight":"#FFF1A8","texture":"grid","displayFont":"poster","wall":"scatter","layout":"loose"},"sections":[{"kind":"intro","title":"three i left early for","songs":[{"trackId":"beaches-blame-brett","why":"left during the encore. traffic."},{"trackId":"metric-help-im-alive","why":"left at the bridge. also traffic."},{"trackId":"orville-peck-dead-of-night","why":"stayed. got home at 2. paid for it at work."}],"stickers":[{"kind":"flower","color":"#FFD23F","x":0.8200000000000001,"y":-0.060000000000000005,"size":54,"rotate":11}]},{"kind":"pinned","title":"the one","trackId":"beaches-blame-brett","note":"The Horseshoe, before any of this. Forty people. I had to leave during the encore to beat the 400. I heard the last song from the sidewalk and it still counts."},{"kind":"shelf","title":"the 400 northbound, 11:40 p.m.","trackIds":["metric-help-im-alive","chappell-good-luck-babe","beaches-blame-brett","shania-man-i-feel"]},{"kind":"wall","title":"records i’d save in a fire","trackIds":["beaches-blame-brett","metric-help-im-alive","chappell-good-luck-babe","orville-peck-dead-of-night","shania-man-i-feel"],"stickers":[{"kind":"star","color":"#FFF4EC","x":0.67,"y":0.52,"size":60,"rotate":-1}]},{"kind":"liner","title":"parking reviews","notes":[{"text":"Twenty-eight dollars to park beside a venue that holds three hundred people. I’d like to speak to the city."},{"trackId":"shania-man-i-feel","text":"Every patient hums along to this in the chair. With my hands in their mouth. That’s commitment."}]},{"kind":"guestbook","title":"sign here","entries":[{"fromId":"maren","trackId":"big-thief-simulation-swarm","why":"the guitar solo sounds like someone falling up the stairs. best one of the decade."},{"fromId":"marisol","trackId":"shania-man-i-feel","why":"first three notes and the whole bar stands up. that’s power. timmins, ontario."},{"fromId":"bea","trackId":"feist-mu