  ('kwame', '{"personId":"kwame","theme":{"paper":"#F2C94C","card":"#FFF6D6","ink":"#14342B","accent":"#C0392B","highlight":"#FFFFFF","texture":"grain","displayFont":"serifBlack","wall":"grid","layout":"loose"},"sections":[{"kind":"pinned","title":"the one","trackId":"fela-water-no-get-enemy","note":"My uncle’s living room in Weston, Sunday after church, the plastic still on the couch. He put it on and the whole room started moving, plastic and all.","stickers":[{"kind":"star","color":"#FFD23F","x":0.8,"y":-0.060000000000000005,"size":58,"rotate":-10}]},{"kind":"intro","title":"three from the van","songs":[{"trackId":"burna-last-last","why":"first job of the day."},{"trackId":"tems-free-mind","why":"lunch, doors open."},{"trackId":"mustafa-stay-alive","why":"last job. quiet drive."}]},{"kind":"wall","title":"on the wall","trackIds":["burna-last-last","fela-water-no-get-enemy","tems-free-mind","kaytranada-10-percent","mustafa-stay-alive","sade-no-ordinary-love"],"stickers":[{"kind":"bolt","color":"#C0392B","x":0.78,"y":0.5800000000000001,"size":60,"rotate":10}]},{"kind":"shelf","title":"sundays","trackIds":["fela-water-no-get-enemy","tems-free-mind","sade-no-ordinary-love","kaytranada-10-percent"]},{"kind":"liner","title":"job notes","notes":[{"text":"My van has better speakers than your apartment. I rewired them myself. It took a weekend and it was the best weekend of my year."},{"trackId":"kaytranada-10-percent","text":"You can wire a whole panel to this and not notice the time."}]},{"kind":"guestbook","title":"visitors’ book","entries":[{"fromId":"malik","trackId":"bbng-time-moves-slow","why":"local boys and a soul legend. play it for your parents, watch them nod."},{"fromId":"marisol","trackId":"shania-man-i-feel","why":"first three notes and the whole bar stands up. that’s power. timmins, ontario."}]},{"kind":"recent","title":"recently played","visibility":"shown","trackIds":["burna-last-last","fela-water-no-get-enemy","tems-free-mind","kaytranada-10-percent"]}]