  ('hyejin', '{"personId":"hyejin","theme":{"paper":"#E9E4F5","card":"#FFF4F8","ink":"#3B2A6B","accent":"#FF5C8A","highlight":"#B8F2E6","texture":"grid","displayFont":"typeBold","wall":"grid","layout":"pages"},"sections":[{"kind":"wall","title":"THE GOOD WALL","trackIds":["newjeans-ditto","slowdive-when-the-sun-hits","yo-la-tengo-autumn-sweater","pavement-gold-soundz","alex-g-runner"],"stickers":[{"kind":"eye","color":"#B8F2E6","x":0.6000000000000001,"y":0.55,"size":50,"rotate":8}]},{"kind":"intro","title":"THREE YOU HAVEN’T HEARD (YOU HAVE)","songs":[{"trackId":"yo-la-tengo-autumn-sweater","why":"track nine. always track nine."},{"trackId":"pavement-gold-soundz","why":"fine, it’s the single. it’s still the best one."},{"trackId":"alex-g-runner","why":"i liked him before. i’m required to say that."}]},{"kind":"pinned","title":"THE PINNED RECORD","trackId":"yo-la-tengo-autumn-sweater","note":"A used CD from a shop on Bloor that isn’t there now. Four dollars. I bought it for the cover and played track nine until the disc gave up.","stickers":[{"kind":"burst","color":"#FFF4F8","x":0.8300000000000001,"y":-0.09000000000000001,"size":52,"rotate":-8}]},{"kind":"shelf","title":"B-SIDES, DEEP CUTS, AND ONE HIT I’M ASHAMED OF","trackIds":["newjeans-ditto","slowdive-when-the-sun-hits","pavement-gold-soundz","alex-g-runner"]},{"kind":"liner","title":"ERRATA","notes":[{"text":"If it charted, I’ll get to it in ten years and act like I found it."},{"trackId":"newjeans-ditto","text":"This charted. I got to it in ten days. Nobody is to mention this."}]},{"kind":"guestbook","title":"GUESTBOOK","entries":[{"fromId":"priya","trackId":"sidhu-295","why":"if you only ever hear one, make it this one. then call me."},{"fromId":"theo","trackId":"american-football-never-meant","why":"you’ve seen the house on the cover. now hear why everyone’s so sad about it."}]},{"kind":"recent","title":"RECENTLY PLAYED","visibility":"hidden","trackIds":[]}]}'::jsonb, app.now_ms()),
  ('dmitri', '{"personId":"dmitri","theme":{"paper":"#1A1A1A","card":"#262626","ink":"#F0F0F0","accent":"#FF3B30","highlight":"#3A3A3A","texture":"grain","displayFont":"poster","wall":"grid","layout":"poster"},"sections":[{"kind":"pinned","title":"the pinned record","trackId":"death-grips-get-got","note":"My condo in Richmond Hill, a Tuesday, new subwoofer just out of the box. I got forty seconds in before the first knock. That knock is framed in my memory.","stickers":[{"kind":"smile","color":"#FF3B30","x":0.8,"y":-0.1,"size":61,"rotate":7}]},{"kind":"intro","title":"three songs my neighbours know","songs":[{"trackId":"death-grips-get-got","why":"unit 1204 knows this one."},{"trackId":"deftones-be-quiet","why":"unit 1206 asked what it was. progress."},{"trackId":"aphex-avril-14th","why":"the apology song. two minutes. very quiet."}]},{"kind":"wall","title":"the good wall","trackIds":["death-grips-get-got","deftones-be-quiet","aphex-avril-14th","four-tet-baby","burial-archangel"],"stickers":[{"kind":"eye","color":"#262626","x":0.6000000000000001,"y":0.73,"size":55,"rotate":-17}]},{"kind":"shelf","title":"subwoofer tests, in order of complaints","trackIds":["death-grips-get-got","burial-archangel","four-tet-baby","deftones-be-quiet"]},{"kind":"liner","title":"notices from the board","notes":[{"text":"Three noise complaints and one compliment. I framed the compliment."},{"trackId":"burial-archangel","text":"The bass on this is so low it’s more of a rumour."}]},{"kind":"guestbook","title":"visitors’ book","entries":[{"fromId":"theo","trackId":"american-football-never-meant","why":"you’ve seen the house on the cover. now hear why everyone’s so sad about it."},{"fromId":"jamal","trackId":"death-grips-get-got","why":"this is the one that got me banned. i regret nothing."}]},{"kind":"recent","title":"recently played","visibility":"shown","trackIds":["death-grips-get-got","deftones-be-quiet","aphex-avril-14th","four-tet-baby"]}]}'::jsonb, app.now_ms()),
  ('tessa', '{"personId":"tessa","theme":{"paper":"#FBFAF4","card":"#FFFFFF","ink":"#23308C","accent":"#1F7A5C","highlight":"#FFF07A","texture":"grid","displayFont":"typeBold","wall":"grid","layout":"loose"},"sections":[{"kind":"intro","title":"THREE PRIMARY SOURCES","songs":[{"trackId":"big-thief-simulation-swarm","why":"see: the guitar solo, which falls up the stairs."},{"trackId":"wednesday-chosen-to-deserve","why":"see: every verse. a confession each."},{"trackId":"cameron-winter-love-takes-miles","why":"see: the way he finds the words as they arrive."}],"stickers":[{"kind":"heart","color":"#FFFFFF","x":0.8300000000000001,"y":-0.07,"size":64,"rotate":5}]},{"kind":"liner","title":"FOOTNOTES","notes":[{"text":"My thesis is about something I can’t explain at parties. The music is easier to explain and I can’t explain that either."},{"trackId":"nick-drake-pink-moon","text":"Twenty-eight minutes, one man, one guitar, and a piano for about ten seconds. Peer review: flawless."}]},{"kind":"pinned","title":"PINNED","trackId":"big-thief-simulation-swarm","note":"Robarts, the thirteenth floor, a carrel with no window. I was 300 words into a chapter I’d been avoiding. I listened twice and wrote two thousand more. The chapter was cut."},{"kind":"shelf","title":"WRITING","trackIds":["nick-drake-pink-moon","sufjan-chicago","big-thief-simulation-swarm"]},{"kind":"wall","title":"THE WALL","trackIds":["big-thief-simulation-swarm","wednesday-chosen-to-deserve","mj-lenderman-shes-leaving-you","cameron-winter-love-takes-miles","nick-drake-pink-moon","sufjan-chicago"],"stickers":[{"kind":"smile","color":"#FFF07A","x":0.56,"y":0.69,"size":62,"rotate":-15}]},{"kind":"shelf","title":"NOT WRITING","trackIds":["mj-lenderman-shes-leaving-you","wednesday-chosen-to-deserve","cameron-winter-love-takes-miles"]},{"kind":"guestbook","title":"VISITORS’ BOOK","entries":[{"fromId":"theo","trackId":"american-football-never-meant","why":"you’ve seen the house on the cover. now hear why everyone’s so sad about it."},{"fromId":"kiran","trackId":"diljit-goat","why":"lakeshore west line, 7:42, window seat. this is the only way to hear it."},{"fromId":"sofia","trackId":"abba-dancing-queen","why":"not ironically. never ironically."}]},{"kind":"recent","title":"LATELY","visibility":"hidden","trackIds":[]}]}'::jsonb, app.now_ms()),
  ('andre', '{"personId":"andre","theme":{"paper":"#0F4C3A","card":"#17604A","ink":"#F3E9D2","accent":"#F2C94C","highlight":"#1F7A5C","texture":"grain","displayFont":"poster","wall":"scatter","layout":"poster"},"sections":[{"kind":"pinned","title":"pinned","trackId":"sade-no-ordinary-love","note":"My aunt’s backyard off Eglinton, I was nine, standing on a milk crate behind two turntables. I played this and my grandmother danced. I’ve been chasing that ever since.","stickers":[{"kind":"flower","color":"#F2C94C","x":0.8400000000000001,"y":-0.09000000000000001,"size":56,"rotate":9}]},{"kind":"intro","title":"three that never miss","songs":[{"trackId":"sade-no-ordinary-love","why":"works at a wedding. works at a wake."},{"trackId":"burna-last-last","why":"for when the uncles need a reason to stand up."},{"trackId":"badu-didnt-cha-know","why":"last song before the lights. everybody sways."}]},{"kind":"shelf","title":"the family function, start to finish","trackIds":["drake-passionfruit","tems-free-mind","burna-last-last","sade-no-ordinary-love"]},{"kind":"wall","title":"the wall","trackIds":["tems-free-mind","burna-last-last","drake-passionfruit","sade-no-ordinary-love","badu-didnt-cha-know"],"stickers":[{"kind":"burst","color":"#FFD23F","x":0.75,"y":0.55,"size":54,"rotate":-11}]},{"kind":"liner","title":"selector’s rules","notes":[{"text":"Read the room before you read the playlist. I read a room faster than you read a menu."},{"trackId":"drake-passionfruit","text":"Start with something everybody already knows. Earn the rest."}]},{"kind":"guestbook","title":"visitors’ book","entries":[{"fromId":"marisol","trackId":"shania-man-i-feel","why":"first three notes and the whole bar stands up. that’s power. timmins, ontario."},{"fromId":"dez","trackId":"dangelo-lady","why":"the bass is behind the beat on purpose. it’s called feel. look it up."},{"fromId":"dev","trackId":"boc-roygbiv","why":"two and a half minutes. headphones, not the phone speaker. i’ll know."}]},{"kind":"recent","title":"lately","visibility":"shown","trackIds":["tems-free-mind","burna-last-last","drake-passionfruit","sade-no-ordinary-love"]}]}'::jsonb, app.now_ms()),
  ('marisol', '{"personId":"marisol","theme":{"paper":"#FFB3C7","card":"#FFF4F8","ink":"#3B2A6B","accent":"#7B2CBF","highlight":"#B8F2E6","texture":"dots","displayFont":"poster","wall":"scatter","layout":"poster"},"sections":[{"kind":"intro","title":"my three-song set","songs":[{"trackId":"shania-man-i-feel","why":"opener. three notes and the room is mine."},{"trackId":"avril-complicated","why":"the breather. everyone knows it. everyone’s flat."},{"trackId":"celine-all-coming-back","why":"closer. do not sign up after me."}],"stickers":[{"kind":"smile","color":"#FFD23F","x":0.8300000000000001,"y":-0.08,"size":59,"rotate":9}]},{"kind":"pinned","title":"the pinned record","trackId":"celine-all-coming-back","note":"The pub by the lake, a Thursday, my first time up. Seven and a half minutes. By the last chorus the bartender had stopped pouring. I have been insufferable since."},{"kind":"shelf","title":"songs i’ve retired other people from singing","trackIds":["abba-dancing-queen","crj-run-away-with-me","nickelback-how-you-remind-me","shania-man-i-feel"],"stickers":[{"kind":"star","color":"#B8F2E6","x":0.8500000000000001,"y":-0.08,"size":63,"rotate":13}]},{"kind":"wall","title":"on the wall","trackIds":["celine-all-coming-back","shania-man-i-feel","avril-complicated","abba-dancing-queen","crj-run-away-with-me","nickelback-how-you-remind-me"],"stickers":[{"kind":"heart","color":"#FFF4F8","x":0.55,"y":0.62,"size":61,"rotate":-7}]},{"kind":"liner","title":"scouting reports","notes":[{"text":"Karaoke is a sport. Thursdays are regionals."},{"trackId":"nickelback-how-you-remind-me","text":"Easy range, big chorus, the whole bar joins in against its will. A perfect karaoke song. I said what I said."}]},{"kind":"guestbook","title":"visitors’ book","entries":[{"fromId":"malik","trackId":"bbng-time-moves-slow","why":"local boys and a soul legend. play it for your parents, watch them nod."},{"fromId":"priya","trackId":"sidhu-295","why":"if you only ever hear one, make it this one. then call me."}]},{"kind":"recent","title":"recently played","visibility":"shown","trackIds":["celine-all-coming-back","shania-man-i-feel","avril-complicated","abba-dancing-queen"]}]}'::jsonb, app.now_ms()),
  ('eli', '{"personId":"eli","theme":{"paper":"#CBAA7C","card":"#EFE2C6","ink":"#2B211B","accent":"#B5301E","highlight":"#F3E3A2","texture":"grain","displayFont":"hand","wall":"scatter","layout":"loose"},"sections":[{"kind":"wall","title":"the wall","trackIds":["pixies-where-is-my-mind","pavement-gold-soundz","sonic-youth-teen-age-riot","yo-la-tengo-autumn-sweater","talking-heads-this-must-be","cure-just-like-heaven"],"stickers":[{"kind":"smile","color":"#B5301E","x":0.79,"y":0.66,"size":52,"rotate":-12}]},{"kind":"pinned","title":"the pinned record","trackId":"pixies-where-is-my-mind","note":"The shop in Kensington, my first Saturday, fifteen and paid in store credit. The owner put this on to see what I’d do. I turned it up. I’ve worked there ever since."},{"kind":"intro","title":"staff picks (all mine)","songs":[{"trackId":"pavement-gold-soundz","why":"every week, until someone stops me."},{"trackId":"sonic-youth-teen-age-riot","why":"the first seven minutes of anyone’s education."},{"trackId":"yo-la-tengo-autumn-sweater","why":"for people who say they don’t like organs."}]},{"kind":"liner","title":"from behind the counter","notes":[{"text":"No, we don’t have it. Yes, I’ve heard of it. No, it isn’t better on vinyl."},{"trackId":"talking-heads-this-must-be","text":"A love song by someone who seems surprised to be having feelings. Relatable."}]},{"kind":"shelf","title":"things i sell and then judge you for","trackIds":["pixies-where-is-my-mind","cure-just-like-heaven","fleetwood-everywhere"]},{"kind":"shelf","title":"things i’d sell you with respect","trackIds":["talking-heads-this-must-be","pavement-gold-soundz","stereolab-french-disko","sonic-youth-teen-age-riot"]},{"kind":"guestbook","title":"guestbook","entries":[{"fromId":"yuki","trackId":"crj-run-away-with-me","why":"the saxophone at the start is a national treasure and we don’t say it enough."},{"fromId":"priya","trackId":"sidhu-295","why":"if you only ever hear one, make it this one. then call me."},{"fromId