  insert into app.posts (user_id, track_id, note, city, created_at, seeded) values
    ('maren', 'big-thief-simulation-swarm', 'put it on in the shop while shelving. three customers asked what it was. sold zero books for ten minutes. worth it.', 'Toronto', at - 3300000, true),
    ('eli', 'pavement-gold-soundz', 'restocked today. again. kensington buys one copy a week like clockwork and i choose to believe it’s the same person.', 'Toronto', at - 7800000, true),
    ('callum', 'pup-kids', 'they’re from here and they sound like the gardiner at rush hour. play it when your landlord texts.', 'Toronto', at - 12000000, true),
    ('amara', 'cdw-work', 'she made this down the road. we forget how much comes out of this city. four minutes of being proud, please.', 'Toronto', at - 19200000, true),
    ('zainab', 'mustafa-stay-alive', 'written about regent park by someone from regent park. if you live here you owe it one proper listen.', 'Toronto', at - 24600000, true),
    ('owen', 'hip-bobcaygeon', 'the bit about toronto is why i moved here. the rest of it is why i still drive north every august.', 'Toronto', at - 30000000, true),
    ('hana', 'slowdive-when-the-sun-hits', 'for anyone on the bus up yonge tonight. it’s snowing a little. this is the correct song.', 'Toronto', at - 42000000, true),
    ('malik', 'bbng-time-moves-slow', 'jazz school kids from this city made this. everyone here should be smug about it.', 'Toronto', at - 50400000, true),
    ('bea', 'feist-mushaboom', 'this was coming out of two different cafés on dundas west this morning. it’s november. somebody’s an optimist.', 'Toronto', at - 60000000, true),
    ('dez', 'miles-so-what', 'trio gig last night, eleven people. opened with this. the eleven were lovely.', 'Toronto', at - 69000000, true),
    ('niamh', 'fontaines-starburster', 'saw them in a room far too big for them and it still felt like a basement. parkdale, back me up.', 'Toronto', at - 78000000, true),
    ('theo', 'american-football-never-meant', 'emo night is friday. consider this your warning and your invitation.', 'Toronto', at - 90000000, true),
    ('clemence', 'wolf-parade-ill-believe', 'toronto, i’m lending you a montréal song. be careful with it. i want it back.', 'Toronto', at - 102000000, true),
    ('kwame', 'burna-last-last', 'every car on weston road had this on all summer and i’m not ready for that to be over.', 'Toronto', at - 114000000, true),
    ('andre', 'sade-no-ordinary-love', 'eglinton west, saturday, a shop door open, this drifting out. nobody was in a hurry for four minutes.', 'Toronto', at - 132000000, true),
    ('ingrid', 'boc-roygbiv', 'the lake was flat this morning and the island ferry was the only thing moving. two and a half minutes. fits exactly.', 'Toronto', at - 150000000, true),
    ('tessa', 'cameron-winter-love-takes-miles', 'thirteenth floor of the library, everyone around me pretending to work. sending this to the whole building.', 'Toronto', at - 174000000, true),
    ('grace', 'glenn-gould-aria', 'there’s a statue of him on a bench downtown. i sat next to it at lunch and played this. he’d have hated that. too many tourists.', 'Toronto', at - 198000000, true),
    ('hyejin', 'yo-la-tengo-autumn-sweater', 'it’s finally sweater weather and i will be insufferable about this song until march.', 'Toronto', at - 222000000, true),
    ('dev', 'burial-archangel', 'the dufferin bus after midnight is this song. i don’t make the rules.', 'Toronto', at - 252000000, true),
    ('wren', 'bill-evans-peace-piece', 'my 4:30 student quit today. i played this afterwards. the junction was very quiet. recommended for endings.', 'Toronto', at - 288000000, true),
    ('mateo', 'bad-bunny-titi', 'st. clair on a saturday. the shop next door complained. i turned it up.', 'Toronto', at - 324000000, true),
    ('jonah', 'steely-dan-peg', 'played this at the thornhill hi-fi meetup (four men, one basement). nobody spoke during the solo. a perfect evening.', 'Vaughan', at - 5400000, true),
    ('sofia', 'abba-dancing-queen', 'woodbridge salon report: three clients, one nonna, everybody singing. this city has taste. it just hides it.', 'Vaughan', at - 22800000, true),
    ('sol', 'peggy-gou-nanana', 'vaughan has no clubs and i’ve made my peace. this is for the subway platform at 11:40, heading home on time.', 'Vaughan', at - 54000000, true),
    ('lucia', 'beaches-blame-brett', 'worth the drive downtown, not worth the parking. play it on the 400 on the way back.', 'Vaughan', at - 108000000, true),
    ('jonah', 'destroyer-kaputt', 'for a mall parking lot at dusk. you’ll understand when you’re in one.', 'Vaughan', at - 234000000, true),
    ('tobi', 'fela-water-no-get-enemy', 'gym, 6 a.m., nobody on the squat rack, this in the big headphones. the best eleven minutes of the week.', 'Mississauga', at - 9600000, true),
    ('marisol', 'shania-man-i-feel', 'thursday at the pub in port credit. i did this one. the lake heard me.', 'Mississauga', at - 37200000, true),
    ('farah', 'mitski-my-love-mine', 'exam season. if you see someone crying efficiently by the library printers, mind your business.', 'Mississauga', at - 84000000, true),
    ('rohan', 'national-bloodbuzz-ohio', 'they’re renovating the food court again. where am i supposed to be sad now.', 'Mississauga', at - 156000000, true),
    ('tobi', 'burna-last-last', 'three different cars playing this at one red light. mississauga has spoken.', 'Mississauga', at - 264000000, true),
    ('priya', 'sidhu-295', 'brampton doesn’t need telling. this is for everybody else reading our feed. start here.', 'Brampton', at - 6600000, true),
    ('kiran', 'diljit-goat', 'the 7:42 from bramalea. if you see a guy nodding with his eyes closed, that’s me, and this is why.', 'Brampton', at - 33600000, true),
    ('jamal', 'kendrick-money-trees', 'played it at a cookout in the park. kept it clean. nobody got hurt. growth.', 'Brampton', at - 96000000, true),
    ('priya', 'ap-dhillon-brown-munde', 'years later and it still comes out of every second car on queen street. the other queen street.', 'Brampton', at - 186000000, true),
    ('yuki', 'newjeans-ditto', 'mall food court, bubble tea, this on loop in one ear. markham is fine, actually.', 'Markham', at - 14400000, true),
    ('arjun', 'deftones-be-quiet', 'walked past our old basement in unionville. someone else’s band was in there playing this. badly. i nearly cried.', 'Markham', at - 75000000, true),
    ('yuki', 'crj-run-away-with-me', 'for whoever else is stuck on highway 7 right now. roll the window down for the sax.', 'Markham', at - 210000000, true),
    ('dmitri', 'death-grips-get-got', 'to my neighbours: it’s this. this is what it’s been.', 'Richmond Hill', at - 28800000, true),
    ('dmitri', 'aphex-avril-14th', 'a peace offering to the whole building. two minutes. i’ll keep it under 40 percent.', 'Richmond Hill', at - 162000000, true),
    ('hana', 'mbv-only-shallow', 'just walked past a guitar shop and someone was trying this riff on a tiny amp. whoever you are: respect.', 'Toronto', at - -240000, true),
    ('kiran', 'burna-last-last', 'train’s delayed. obviously. this is making the platform bearable.', 'Brampton', at - -600000, true),
    ('sofia', 'chappell-good-luck-babe', 'last client of the day asked for “that one again.” third time. no complaints from me.', 'Vaughan', at - -1080000, true),
    ('eli', 'talking-heads-this-must-be', 'someone just bought this on vinyl for their partner and blushed at the till. kensington is alright sometimes.', 'Toronto', at - -1680000, true),
    ('marisol', 'celine-all-coming-back', 'warming up. port credit, you’ve been warned.', 'Mississauga', at - -2700000, true),
    ('callum', 'fucked-up-queen-of-hearts', 'close is done, kitchen’s clean, this is going on the speaker. east end, if you can hear it: hi.', 'Toronto', at - -3900000, true),
    ('amara', 'sza-good-days', 'break. fifteen minutes. this, and nobody talk to me.', 'Toronto', at - -5700000, true),
    ('yuki', 'magdalena-bay-death-romance', 'the render’s at 91 percent. this is the only thing keeping me in the chair.', 'Markham', at - -7800000, true);
  insert into app.threads (artist_key, artist, city, user_id, title, body, created_at, seeded)
  insert into app.replies (thread_id, user_id, body, track_id, created_at, seeded) values
    (tid, 'tessa', 'simulation swarm. it’s the friendliest door in. if she doesn’t like the guitar solo you may need a new sister.', 'big-thief-simulation-swarm', least(at - 60000, at - 777600000 + 7200000), true),
    (tid, 'bea', 'not. play it loud. “sad folk band” will not survive the last two minutes.', 'big-thief-not', least(at - 60000, at - 777600000 + 18000000), true),
    (tid, 'hana', 'controversial: don’t play a song, play a live video where the amp is clearly about to die. context matters.', null, least(at - 60000, at - 777600000 + 72000000), true),
    (tid, 'callum', 'vampire empire. the only time folk music has made me want to shove someone, affectionately.', 'big-thief-vampire-empire', least(at - 60000, at - 777600000 + 111600000), true),
    (tid, 'maren', 'update: went with simulation swarm. she asked to hear it again. i’m not saying i cried in the car but the car was involved.', null, least(at - 60000, at - 777600000 + 360000000), true);
  insert into app.threads (artist_key, artist, city, user_id, title, body, created_at, seeded)
  insert into app.replies (thread_id, user_id, body, track_id, created_at, seeded) values
    (tid, 'maren', 'me. i’ll be near the sound desk pretending i’m not emotional. send me a song and we’ll sort it out.', null, least(at - 60000, at - 259200000 + 10800000), true),
    (tid, 'bea', 'i’m in if it’s seated. my knees have opinions now.', null, least(at - 60000, at - 259200000 + 32400000), true),
    (tid, 'niamh', 'came for the thread, staying for “my knees have opinions.” i’ll come. parkdale contingent.', null, least(at - 60000, at - 259200000 + 108000000), true),
    (tid, 'tessa', 'ok, that’s four of us. i’ll make a plan. someone send me a song so we’ve got a chat going.', null, at + 360000, true);
  insert into app.threads (artist_key, artist, city, user_id, title, body, created_at, seeded)
  insert into app.replies (thread_id, user_id, body, track_id, created_at, seeded) values
    (tid, 'maren', 'any version of archie where the whole room does the “hey.” the crowd is the instrument.', 'alvvays-archie', least(at - 60000, at - 1036800000 + 14400000), true),
    (tid, 'hyejin', 'belinda says, any live take. the key change lands harder when you can hear four hundred people brace for it.', 'alvvays-belinda-says', least(at - 60000, at - 1036800000 + 39600000), true),
    (tid, 'eli', 'a bootleg tape came through the shop once. sold in an hour. i never even got to play it. still bitter.', null, least(at - 60000, at - 1036800000 + 180000000), true),
    (tid, 'clemence', 'i saw them in a church basement in montréal and the pa caught fire, a little. best show i’ve seen. no recording exists, which is correct.', null, least(at - 60000, at - 1036800000 + 432000000), true);
  insert into app.threads (artist_key, artist, city, user_id, title, body, created_at, seeded)
  insert into app.replies (thread_id, user_id, body, track_id, created_at, seeded) values
    (tid, 'theo', '1. someone falls, you pick them up. 2. shoes tied. 3. earplugs aren’t optional. ask my left ear.', null, least(at - 60000, at - 518400000 + 3600000), true),
    (tid, 'niamh', 'tell him to stand at the side for two songs and watch how it moves first. it’s weather. you learn to read it.', null, least(at - 60000, at - 518400000 + 21600000), true),
    (tid, 'arjun', 'don’t wear the band’s shirt to the band’s show. i don’t make the rules. (i do. nobody’s ever challenged me.)', null, least(at - 60000, at - 518400000 + 93600000), true),
    (tid, 'callum', 'report: he lost a shoe and gained a personality. thank you all.', 'pup-kids', least(at - 60000, at - 518400000 + 345600000), true);
  insert into app.threads (artist_key, artist, city, user_id, title, body, created_at, seeded)
  insert into app.replies (thread_id, user_id, body, track_id, created_at, seeded) values
    (tid, 'dez', 'IV, and start at time moves slow. the bassline does the convincing for you.', 'bbng-time-moves-slow', least(at - 60000, at - 1296000000 + 10800000), true),
    (tid, 'dev', 'the early stuff where they’re covering rap songs in a rehearsal room. it’s messy and you can hear them working out that they’re a band.', null, least(at - 60000, at - 1296000000 + 50400000), true),
    (tid, 'wren', 'i play them for students who say jazz is homework. it works about half the time, which for jazz is a miracle.', null, least(at - 60000, at - 1296000000 + 144000000), true),
    (tid, 'kwame', 'my van approves. that’s it. that’s the review.', null, least(at - 60000, at - 1296000000 + 720000000), true);
  insert into app.threads (artist_key, artist, city, user_id, title, body, created_at, seeded)
  insert into app.replies (thread_id, user_id, body, track_id, created_at, seeded) values
    (tid, 'kiran', '295. no debate. then we can argue about second place for a week.', 'sidhu-295', least(at - 60000, at - 691200000 + 3600000), true),
    (tid, 'jamal', 'i don’t speak a word of punjabi and i’ve had 295 on repeat since a cookout in 2021. brampton did that to me. thank you.', null, least(at - 60000, at - 691200000 + 25200000), true),
    (tid, 'priya', 'jamal, you’re one of us now. there’s paperwork.', null, least(at - 60000, at - 691200000 + 28800000), true),
    (tid, 'tobi', 'visiting from mississauga. started with 295 like you said. it’s been three days. send help, or send more.', null, least(at - 60000, at - 691200000 + 252000000), true);
  insert into app.threads (artist_key, artist, city, user_id, title, body, created_at, seeded)
  insert into app.replies (thread_id, user_id, body, track_id, created_at, seeded) values
    (tid, 'kwame', 'it’s a driving song. you’re both wrong. respectfully.', null, least(at - 60000, at - 345600000 + 7200000), true),
    (tid, 'andre', 'it’s a first-hour-of-the-party song. i’ve tested this at eleven family functions.', null, least(at - 60000, at - 345600000 + 18000000), true),
    (tid, 'jamal', 'it’s an apology song. i use it to get the aux back.', null, least(at - 60000, at - 345600000 + 68400000), true),
    (tid, 'kiran', 'it’s a delayed-train song. i have data.', null, least(at - 60000, at - 345600000 + 158400000), true),
    (tid, 'tobi', 'none of you have settled anything. it’s a warm-up song.', null, at + 1800000, true);
  insert into app.threads (artist_key, artist, city, user_id, title, body, created_at, seeded)
  insert into app.replies (thread_id, user_id, body, track_id, created_at, seeded) values
    (tid, 'dez', 'the one where the solo goes on too long and the drummer is visibly judging. i learned everything i know from that drummer’s face.', null, least(at - 60000, at - 1728000000 + 21600000), true),
    (tid, 'sol', 'i’m 26 and i only know peg from a sample. am i allowed in here', null, least(at - 60000, at - 1728000000 + 108000000), true),
    (tid, 'jonah', 'sol, yes. everyone gets in through a sample. welcome. there’s reading.', null, least(at - 60000, at - 1728000000 + 111600000), true),
    (tid, 'malik', 'my dad owns three copies of aja “in case.” in case of what, he won’t say.', null, least(at - 60000, at - 1728000000 + 540000000), true);
  insert into app.threads (artist_key, artist, city, user_id, title, body, created_at, seeded)
  insert into app.replies (thread_id, user_id, body, track_id, created_at, seeded) values
    (tid, 'arjun', 'it isn’t one pedal, it’s two reverbs arguing. also a lot of volume. sorry about your landlord.', null, least(at - 60000, at - 950400000 + 10800000), true),
    (tid, 'ingrid', 'i don’t play anything. i just want to say this thread is very soothing to read.', null, least(at - 60000, at - 950400000 + 36000000), true),
    (tid, 'dev', 'engineer here. half of it is the room. you can’t buy the room. i’ve tried.', null, least(at - 60000, at - 950400000 + 100800000), true),
    (tid, 'hana', '“you can’t buy the room” is going on my amp in tape.', null, least(at - 60000, at - 950400000 + 104400000), true);
  insert into app.threads (artist_key, artist, city, user_id, title, body, created_at, seeded)
  insert into app.replies (thread_id, user_id, body, track_id, created_at, seeded) values
    (tid, 'maren', 'back of my cousin’s corolla on the 401. it’s pinned in my room. i will not shut up about it.', null, least(at - 60000, at - 1555200000 + 7200000), true),
    (tid, 'bea', 'arranging tulips. cried on the tulips. sold them anyway.', null, least(at - 60000, at - 1555200000 + 32400000), true),
    (tid, 'clemence', 'a kitchen in montréal. someone told me it was a toronto band and i refused to believe it.', null, least(at - 60000, at - 1555200000 + 162000000), true),
    (tid, 'eli', 'behind the counter. a customer asked “what is this” and i got to say “local.” best day at work.', null, least(at - 60000, at - 1555200000 + 468000000), true);
  insert into app.threads (artist_key, artist, city, user_id, title, body, created_at, seeded)
  insert into app.replies (thread_id, user_id, body, track_id, created_at, seeded) values
    (tid, 'grace', 'i’ve never been to anything like this. is it weird to come alone? i know all the piano parts.', null, least(at - 60000, at - 172800000 + 14400000), true),
    (tid, 'owen', 'grace, that’s the least weird thing anyone’s said in here. come. bring the piano parts.', null, least(at - 60000, at - 172800000 + 18000000), true),
    (tid, 'lucia', 'driving in from maple if parking’s under twenty dollars. it won’t be. i’ll come anyway.', null, least(at - 60000, at - 172800000 + 79200000), true);
  insert into app.threads (artist_key, artist, city, user_id, title, body, created_at, seeded)
  insert into app.replies (thread_id, user_id, body, track_id, created_at, seeded) values
    (tid, 'yuki', 'von dutch. two seconds in and people sit up straight.', 'charli-von-dutch', least(at - 60000, at - 432000000 + 7200000), true),
    (tid, 'sol', 'i’ve seen a whole brunch stop for it. the eggs went cold. nobody minded.', null, least(at - 60000, at - 432000000 + 28800000), true),
    (tid, 'marisol', 'it can’t be done at karaoke. i tried. it’s my only failure and i think about it often.', null, least(at - 60000, at - 432000000 + 180000000), true);
  insert into app.threads (artist_key, artist, city, user_id, title, body, created_at, seeded)
  insert into app.replies (thread_id, user_id, body, track_id, created_at, seeded) values
    (tid, 'amara', 'my love mine all mine. two eighteen. i checked it against the clock in the break room.', 'mitski-my-love-mine', least(at - 60000, at - 604800000 + 21600000), true),
